// ---------------------------------------------------------------- interface language
// Keys are the English text of the page. Text that is not in the table stays in English.
// Chat messages, code, parameter files and file names are never translated.
const LANGS = [["en-US", "English (US)"], ["en-GB", "English (UK)"], ["el", "Ελληνικά"],
               ["es", "Español"], ["de", "Deutsch"], ["it", "Italiano"]];
const US_SPELLING = [[/\bcolour/g, "color"], [/\bColour/g, "Color"], [/\banalys(e|ed|es|ing)\b/g, "analyz$1"],
                     [/\bAnalys(e|ed|es|ing)\b/g, "Analyz$1"], [/\bspecialised/g, "specialized"],
                     [/\bSpecialised/g, "Specialized"], [/\bcentre\b/g, "center"], [/\bneighbour/g, "neighbor"],
                     [/\bpolarisation/g, "polarization"], [/\bcatalogue/g, "catalog"]];
const I18N_SKIP = ".msg, .gmsg, pre, code, svg, script, style, .ht, .rl, .rc-label, .qscroll, .rx, .files, .codebar span, [data-noi18n]";
const I18N_ATTRS = ["title", "placeholder", "aria-label", "alt"];

const i18n = (() => {
  const norm = s => s.replace(/\s+/g, " ").trim();
  const detect = () => {
    try { const v = localStorage.getItem("spinmate.lang"); if (LANGS.some(l => l[0] === v)) return v; } catch {}
    const n = navigator.language || "en-US";
    if (/^en-(GB|IE|AU|NZ|ZA|IN)/i.test(n)) return "en-GB";
    const b = n.slice(0, 2).toLowerCase();
    return ["el", "es", "de", "it"].includes(b) ? b : "en-US";
  };
  let lang = detect(), dict = null, pats = [];
  const miss = new Set();
  function build() {
    dict = I18N[lang] || null; pats = [];
    if (!dict) return;
    for (const [k, v] of Object.entries(dict)) {
      if (!/\{#?\w+\}/.test(k)) continue;
      // {name} matches any text, {#name} only a number
      const names = [];
      const src = k.replace(/[.*+?^$()|[\]\\]/g, "\\$&").replace(/\{(#?)(\w+)\}/g, (_, h, n) => { names.push(n); return h ? "([\\d.,\\s\u202f]+)" : "([\\s\\S]+?)"; });
      pats.push([new RegExp("^" + src + "$"), names, v, k.replace(/\{#?\w+\}/g, "").length]);
    }
    pats.sort((a, b) => b[3] - a[3]);   // the most specific pattern wins
  }
  const fill = (s, vars) => s.replace(/\{(\w+)\}/g, (m, k) => vars && vars[k] !== undefined ? vars[k] : m);
  const us = s => US_SPELLING.reduce((a, [re, to]) => a.replace(re, to), s);
  // translated text for an English string, or null when it stays as it is
  function look(s) {
    if (lang === "en-US") { const u = us(s); return u === s ? null : u; }
    if (!dict) return null;
    if (dict[s] !== undefined) return dict[s];
    for (const [re, names, v] of pats) {
      const m = s.match(re); if (!m) continue;
      const vars = {}; names.forEach((n, i) => { vars[n] = dict[m[i + 1]] !== undefined ? dict[m[i + 1]] : m[i + 1]; });
      return fill(v, vars);
    }
    if (/\p{L}{2}/u.test(s)) miss.add(s);
    return null;
  }
  function t(s, vars) { const v = look(s); return fill(v === null ? s : v, vars); }

  const texts = new WeakMap(), attrs = new WeakMap(), htmls = new WeakMap();
  function trText(n) {
    const rec = texts.get(n), orig = rec && n.data === rec[1] ? rec[0] : n.data;
    const core = norm(orig); if (!core || !/\p{L}/u.test(core)) return;
    const v = look(core), m = orig.match(/^(\s*)[\s\S]*?(\s*)$/);
    const out = v === null ? orig : m[1] + v + m[2];
    texts.set(n, [orig, out]); if (n.data !== out) n.data = out;
  }
  function trAttr(el, a) {
    const cur = el.getAttribute(a); if (cur === null) return;
    let rec = attrs.get(el); if (!rec) { rec = {}; attrs.set(el, rec); }
    const orig = rec[a] && cur === rec[a][1] ? rec[a][0] : cur;
    const core = norm(orig); if (!/\p{L}/u.test(core)) return;
    const v = look(core), out = v === null ? orig : v;
    rec[a] = [orig, out]; if (cur !== out) el.setAttribute(a, out);
  }
  // a paragraph with bold words or links is translated as one piece of HTML
  function trHtml(el) {
    let rec = htmls.get(el);
    if (rec && el.innerHTML !== rec[1]) { htmls.delete(el); rec = null; }   // the page replaced the content
    const orig = rec ? rec[0] : el.innerHTML, key = norm(orig);
    const v = dict && el.childElementCount <= 8 && key.length < 900 && /^(P|H2|H3|H4|LI|SPAN|DIV|LABEL|SMALL)$/.test(el.tagName) ? dict[key] : undefined;
    if (v === undefined) { if (rec) { htmls.delete(el); el.innerHTML = orig; } return false; }
    htmls.set(el, [orig, v]); if (el.innerHTML !== v) el.innerHTML = v;
    return true;
  }
  function walk(n) {
    if (n.nodeType === 3) return trText(n);
    if (n.nodeType !== 1 || n.matches(I18N_SKIP)) return;
    for (const a of I18N_ATTRS) if (n.hasAttribute(a)) trAttr(n, a);
    if (n.childElementCount && trHtml(n)) return;
    for (const c of [...n.childNodes]) walk(c);
  }
  const skipped = n => { const p = n.nodeType === 1 ? n : n.parentElement; return !p || !p.isConnected || !!p.closest(I18N_SKIP); };
  function inHtml(n) {   // inside a block that was translated as a whole
    for (let p = n.parentElement; p; p = p.parentElement) if (htmls.has(p)) return true;
    return false;
  }
  const obs = new MutationObserver(ms => {
    for (const m of ms) {
      if (m.type === "childList") { for (const n of m.addedNodes) if (!skipped(n) && !inHtml(n)) walk(n); }
      else if (m.type === "characterData") { if (!skipped(m.target) && !inHtml(m.target)) trText(m.target); }
      else if (!skipped(m.target)) trAttr(m.target, m.attributeName);
    }
  });
  function apply() { document.documentElement.lang = lang; walk(document.body); }
  function set(v) {
    if (!LANGS.some(l => l[0] === v)) return;
    lang = v; try { localStorage.setItem("spinmate.lang", v); } catch {}
    build(); apply(); document.dispatchEvent(new CustomEvent("langchange", {detail: v}));
  }
  function start() {
    build(); apply();
    obs.observe(document.body, {childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: I18N_ATTRS});
  }
  return {t, set, start, lang: () => lang, miss, name: () => (LANGS.find(l => l[0] === lang) || LANGS[0])[1]};
})();
const t = i18n.t;

