  "Streamable HTTP. Large requests return needs_confirmation, so the agent asks you before it runs them.": "Streamable HTTP. Τα μεγάλα αιτήματα επιστρέφουν needs_confirmation, οπότε ο agent σας ρωτά πριν τα τρέξει.",
  "The commands that add SpinMate to Claude Code, Claude Desktop or any MCP agent, with copy buttons.": "Οι εντολές που προσθέτουν το SpinMate στο Claude Code, στο Claude Desktop ή σε οποιονδήποτε MCP agent, με κουμπιά αντιγραφής.",
  "Shows that the solver passes its analytic checks (resonance frequencies, energy, damping, the AFM/FM boundary). Green when all cases pass; click for the full report and the phase diagram.": "Δείχνει ότι ο solver περνά τους αναλυτικούς ελέγχους του (συχνότητες συντονισμού, ενέργεια, απόσβεση, όριο AFM/FM). Πράσινο όταν περνούν όλες οι περιπτώσεις· πατήστε για την πλήρη αναφορά και το διάγραμμα φάσεων.",
  "Valid. {#n} steps.": "Έγκυρο. {n} βήματα.",
