  "Model behind each god": "Μοντέλο πίσω από κάθε θεό",
  "Auto scores the god's models from every provider you have a key for (Anthropic, OpenAI, Gemini) by capability and price for each request, and switches to the next one if a call fails. Choose a model to always use it for that god.": "Το Auto βαθμολογεί για κάθε αίτημα τα μοντέλα του θεού από κάθε πάροχο για τον οποίο έχετε κλειδί (Anthropic, OpenAI, Gemini) με βάση την ικανότητα και την τιμή, και περνά στο επόμενο αν μια κλήση αποτύχει. Διαλέξτε μοντέλο για να χρησιμοποιείται πάντα για αυτόν τον θεό.",
