  "Publication figure": "Γράφημα δημοσίευσης",
  "Drawn on the server with matplotlib and SciencePlots. The figure appears in the chat, where you can download it as PDF, SVG or 300 dpi PNG.": "Σχεδιάζεται στον server με matplotlib και SciencePlots. Το γράφημα εμφανίζεται στη συζήτηση, όπου μπορείτε να το κατεβάσετε ως PDF, SVG ή PNG 300 dpi.",
