  "Add to chat": "Προσθήκη στη συζήτηση",
  "Preview": "Προεπισκόπηση",
  "Method, results table, parameters, figures and the parameter files of the runs. It appears in the chat, where you can read it, print it to PDF or download it.": "Μέθοδος, πίνακας αποτελεσμάτων, παράμετροι, γραφήματα και τα αρχεία παραμέτρων των εκτελέσεων. Εμφανίζεται στη συζήτηση, όπου μπορείτε να τη διαβάσετε, να την εκτυπώσετε σε PDF ή να την κατεβάσετε.",
  "Discussion": "Συζήτηση αποτελεσμάτων",
  "Optional, Markdown. Or let the assistant write it.": "Προαιρετικό, Markdown. Ή αφήστε τον βοηθό να το γράψει.",
  "Create report": "Δημιουργία αναφοράς",
  "Ask the assistant to write it": "Ζητήστε από τον βοηθό να τη γράψει",
  "Conversations": "Συζητήσεις",
  "No conversations yet.": "Δεν υπάρχουν ακόμα συζητήσεις.",
  "Select conversation": "Επιλογή συζήτησης",
  "Delete conversation": "Διαγραφή συζήτησης",
  "Saved in this browser. They are the starting point of Fast mode and are sent to the assistant as the base of every run.": "Αποθηκεύονται σε αυτόν τον browser. Είναι η αφετηρία της λειτουργίας Fast και στέλνονται στον βοηθό ως βάση κάθε εκτέλεσης.",
  "Save": "Αποθήκευση",
  "Reset to built-in": "Επαναφορά αρχικών",
  "Cancel": "Ακύρωση",
  "Duration (ns)": "Διάρκεια (ns)",
  "Saturation Ms (kA/m)": "Μαγνήτιση κόρου Ms (kA/m)",
  "Exchange A0 (pJ/m)": "Ανταλλαγή A0 (pJ/m)",
  "Anisotropy Ku (10⁴ J/m³)": "Ανισοτροπία Ku (10⁴ J/m³)",
  "Damping α": "Απόσβεση α",
  "Temperature (K)": "Θερμοκρασία (K)",
  "SOT current (10⁶ A/cm²)": "Ρεύμα SOT (10⁶ A/cm²)",
  "{label} slider": "Ολισθητής: {label}",
  "Find a skill": "Βρείτε μια δεξιότητα",
  "Hi, what shall we simulate?": "Γεια σας, τι θα προσομοιώσουμε;",
  "Hi {name}, what shall we simulate?": "Γεια σου {name}, τι θα προσομοιώσουμε;",
  "Describe the conditions in words or attach a parameter file. The agent checks them with the solver's own parser, runs the two-sublattice macrospin model, and explains the result from the real dynamics.": "Περιγράψτε τις συνθήκες με λόγια ή επισυνάψτε αρχείο παραμέτρων. Ο agent τις ελέγχει με τον parser του ίδιου του solver, τρέχει το macrospin μοντέλο δύο υποπλεγμάτων και εξηγεί το αποτέλεσμα από την πραγματική δυναμική.",
  "Parameters": "Παράμετροι",
  "Start antiferromagnetic with a positive exchange A0 = 0.248e-12, no current, 2 ns. Does it end ferromagnetic?": "Ξεκίνα αντισιδηρομαγνητικά με θετική ανταλλαγή A0 = 0.248e-12, χωρίς ρεύμα, 2 ns. Καταλήγει σιδηρομαγνητικό;",
  "Start antiferromagnetic with the negative default exchange, no current, 2 ns. Does it stay antiferromagnetic?": "Ξεκίνα αντισιδηρομαγνητικά με την αρνητική προεπιλεγμένη ανταλλαγή, χωρίς ρεύμα, 2 ns. Μένει αντισιδηρομαγνητικό;",
  "Start with nearly parallel sublattices (m1 = 0.25,0,0.968 and m2 = 0.35,0,0.937) and a negative exchange A0 = -0.248e-12, no current, 2 ns. Does it become antiferromagnetic?": "Ξεκίνα με σχεδόν παράλληλα υποπλέγματα (m1 = 0.25,0,0.968 και m2 = 0.35,0,0.937) και αρνητική ανταλλαγή A0 = -0.248e-12, χωρίς ρεύμα, 2 ns. Γίνεται αντισιδηρομαγνητικό;",
  "Start with nearly parallel sublattices (m1 = 0.25,0,0.968 and m2 = 0.35,0,0.937) and a positive exchange A0 = 0.248e-12, no current, 2 ns. Does it stay ferromagnetic?": "Ξεκίνα με σχεδόν παράλληλα υποπλέγματα (m1 = 0.25,0,0.968 και m2 = 0.35,0,0.937) και θετική ανταλλαγή A0 = 0.248e-12, χωρίς ρεύμα, 2 ns. Μένει σιδηρομαγνητικό;",
  "Heat a FeRh layer through its transition: positive A0 = 0.248e-12, temperature 370 K ± 60 K at 0.25 GHz, 2 ns. When does it go from AFM to FM?": "Θέρμανε ένα στρώμα FeRh μέσα από τη μετάβασή του: θετικό A0 = 0.248e-12, θερμοκρασία 370 K ± 60 K στα 0.25 GHz, 2 ns. Πότε περνά από AFM σε FM;",
  "Explain which parameters I can set and their units.": "Εξήγησε ποιες παραμέτρους μπορώ να ορίσω και τις μονάδες τους.",
