  "varies": "ποικίλλει",
  "No model available. Add an API key in Settings.": "Κανένα διαθέσιμο μοντέλο. Προσθέστε κλειδί API στις Ρυθμίσεις.",
  "Uses": "Χρησιμοποιεί",
  "The browser blocks the microphone on this address; open SpinMate on localhost or https.": "Ο browser μπλοκάρει το μικρόφωνο σε αυτή τη διεύθυνση· ανοίξτε το SpinMate σε localhost ή https.",
  "No OpenAI key: the browser's dictation is used, always with the system default microphone. Add an OpenAI key to choose one.": "Χωρίς κλειδί OpenAI: χρησιμοποιείται η υπαγόρευση του browser, πάντα με το προεπιλεγμένο μικρόφωνο. Προσθέστε κλειδί OpenAI για να διαλέξετε.",
  "Voice input needs an OpenAI key (Settings).": "Η φωνητική εισαγωγή χρειάζεται κλειδί OpenAI (Ρυθμίσεις).",
  "Names appear after you allow the microphone once.": "Τα ονόματα εμφανίζονται αφού επιτρέψετε μία φορά το μικρόφωνο.",
  "Speech is transcribed by OpenAI and put in the message box; nothing is sent until you press Enter.": "Η ομιλία μεταγράφεται από το OpenAI και μπαίνει στο πλαίσιο μηνύματος· τίποτα δεν στέλνεται πριν πατήσετε Enter.",
  "Recording: click to stop (Esc cancels)": "Εγγραφή: πατήστε για διακοπή (Esc για ακύρωση)",
  "Transcribing…": "Μεταγραφή…",
  "user guide (PDF)": "οδηγός χρήσης (PDF)",
  "and the": "και η",
  "presentation (PDF)": "παρουσίαση (PDF)",
  "Welcome back, {name}! I'm Athena, your guide.": "Καλώς ήρθατε ξανά, {name}! Είμαι η Αθηνά, ο οδηγός σας.",
  "Welcome to SpinMate! I'm Athena, your guide.": "Καλώς ήρθατε στο SpinMate! Είμαι η Αθηνά, ο οδηγός σας.",
  "I can also show you around the app: where things are and what the buttons do.": "Μπορώ επίσης να σας δείξω την εφαρμογή: πού είναι τα πράγματα και τι κάνουν τα κουμπιά.",
  "Before we begin, what's your name?": "Πριν ξεκινήσουμε, πώς σας λένε;",
  "No problem, no account needed. Here is your {docs}; you can also ask me for them any time. Ask me anything about using SpinMate, or pick a question:": "Κανένα πρόβλημα, δεν χρειάζεται λογαριασμός. Ορίστε: {docs}· μπορείτε να μου τα ζητήσετε όποτε θέλετε. Ρωτήστε με οτιδήποτε για τη χρήση του SpinMate ή διαλέξτε μια ερώτηση:",
  "That doesn't look like an email address. Try again, or press Skip for now.": "Αυτό δεν μοιάζει με διεύθυνση email. Δοκιμάστε ξανά ή πατήστε Παράλειψη προς το παρόν.",
  "Creating your account…": "Δημιουργία λογαριασμού…",
  "Your account is ready! I've sent a welcome email to **{email}** with the documents attached. You can also open the {docs} here. Ask me anything, or pick a question:": "Ο λογαριασμός σας είναι έτοιμος! Έστειλα email καλωσορίσματος στο **{email}** με τα έγγραφα συνημμένα. Μπορείτε να ανοίξετε και εδώ: {docs}. Ρωτήστε με οτιδήποτε ή διαλέξτε μια ερώτηση:",
  "Your account is ready, but the welcome email could not be sent ({error}). Here is your {docs}. Ask me anything, or pick a question:": "Ο λογαριασμός σας είναι έτοιμος, αλλά το email καλωσορίσματος δεν στάλθηκε ({error}). Ορίστε: {docs}. Ρωτήστε με οτιδήποτε ή διαλέξτε μια ερώτηση:",
  "Your account is ready! Here is your {docs}. Ask me anything, or pick a question:": "Ο λογαριασμός σας είναι έτοιμος! Ορίστε: {docs}. Ρωτήστε με οτιδήποτε ή διαλέξτε μια ερώτηση:",
  "I couldn't create the account: {error}. Try again, or press Skip for now.": "Δεν μπόρεσα να δημιουργήσω τον λογαριασμό: {error}. Δοκιμάστε ξανά ή πατήστε Παράλειψη προς το παρόν.",
  "I can only help with using SpinMate: the chat, Fast and Deep modes, run setup, runs and results, settings and the API key. Ask me about any of those.": "Μπορώ να βοηθήσω μόνο με τη χρήση του SpinMate: τη συζήτηση, τις λειτουργίες Fast και Deep, τη ρύθμιση εκτέλεσης, τις εκτελέσεις και τα αποτελέσματα, τις ρυθμίσεις και το κλειδί API. Ρωτήστε με για οποιοδήποτε από αυτά.",
  "I couldn't read that. Please type just your first name.": "Δεν μπόρεσα να το διαβάσω. Γράψτε μόνο το μικρό σας όνομα.",
  "Nice to meet you, {name}! Want an account? Type your email and I'll send you a welcome email with the SpinMate user guide and the presentation. Your email is used for this welcome email and kept by the SpinMate author, only to contact you about SpinMate; write to spinmate.ai.agent@gmail.com to have it deleted. Or press Skip for now: you get them here either way.": "Χαίρω πολύ, {name}! Θέλετε λογαριασμό; Γράψτε το email σας και θα σας στείλω email καλωσορίσματος με τον οδηγό χρήσης του SpinMate και την παρουσίαση. Το email σας χρησιμοποιείται για αυτό το email καλωσορίσματος και το κρατά ο δημιουργός του SpinMate μόνο για να επικοινωνήσει μαζί σας για το SpinMate· γράψτε στο spinmate.ai.agent@gmail.com για να διαγραφεί. Ή πατήστε Παράλειψη προς το παρόν: θα τα πάρετε εδώ ούτως ή άλλως.",
  "Nice to meet you, {name}! Want an account? Type your email and I'll send you a welcome email with the SpinMate user guide. Your email is used for this welcome email and kept by the SpinMate author, only to contact you about SpinMate; write to spinmate.ai.agent@gmail.com to have it deleted. Or press Skip for now: you get them here either way.": "Χαίρω πολύ, {name}! Θέλετε λογαριασμό; Γράψτε το email σας και θα σας στείλω email καλωσορίσματος με τον οδηγό χρήσης του SpinMate. Το email σας χρησιμοποιείται για αυτό το email καλωσορίσματος και το κρατά ο δημιουργός του SpinMate μόνο για να επικοινωνήσει μαζί σας για το SpinMate· γράψτε στο spinmate.ai.agent@gmail.com για να διαγραφεί. Ή πατήστε Παράλειψη προς το παρόν: θα τον πάρετε εδώ ούτως ή άλλως.",
