  "Pick a parameter in convenient units, the range and the steps (or what to look for), and the duration. It writes a clear request with SI values and warns about unusual numbers.": "Elige un parámetro en unidades cómodas, el rango y los pasos (o lo que buscas) y la duración. Escribe una petición clara con valores SI y avisa de números inusuales.",
  "Click the token counter for the tokens and the cost per day and per provider (Claude, OpenAI, Gemini) of every answer on this server.": "Haz clic en el contador de tokens para ver los tokens y el coste por día y por proveedor (Claude, OpenAI, Gemini) de cada respuesta de este servidor.",
  "Under an answer: sends the same question to another model level and shows both answers side by side.": "Bajo una respuesta: envía la misma pregunta a otro nivel de modelo y muestra las dos respuestas lado a lado.",
