  "Opening Claude Code in the repository also loads the physics subagent and skill.": "Al abrir Claude Code en el repositorio también se cargan el subagente y la skill de física.",
  "Settings > Developer > Edit config (claude_desktop_config.json); change the path to your copy of the repository.": "Ajustes > Developer > Edit config (claude_desktop_config.json); cambia la ruta a tu copia del repositorio.",
  "Streamable HTTP. Large requests return needs_confirmation, so the agent asks you before it runs them.": "Streamable HTTP. Las peticiones grandes devuelven needs_confirmation, así que el agente te pregunta antes de ejecutarlas.",
  "The commands that add SpinMate to Claude Code, Claude Desktop or any MCP agent, with copy buttons.": "Los comandos que añaden SpinMate a Claude Code, Claude Desktop o cualquier agente MCP, con botones para copiar.",
  "Shows that the solver passes its analytic checks (resonance frequencies, energy, damping, the AFM/FM boundary). Green when all cases pass; click for the full report and the phase diagram.": "Muestra que el solver supera sus comprobaciones analíticas (frecuencias de resonancia, energía, amortiguamiento, el límite AFM/FM). Verde cuando pasan todos los casos; haz clic para el informe completo y el diagrama de fases.",
