  "Lists your earlier chats with their runs and graphs. Click one to reopen it, or the cross to delete it. Every user has their own history.": "Muestra tus chats anteriores con sus ejecuciones y gráficas. Pulsa uno para reabrirlo o la cruz para borrarlo. Cada usuario tiene su propio historial.",
  "Runs": "Ejecuciones",
  "Edit the values Fast mode starts from: duration, Ms, exchange A0, anisotropy Ku, damping, temperature, SOT current, the initial state and one or two extra flags. They are saved in this browser and also sent to the assistant as the base of its runs. “Reset to built-in” brings back the originals.": "Edita los valores de partida del modo Fast: duración, Ms, intercambio A0, anisotropía Ku, amortiguamiento, temperatura, corriente SOT, el estado inicial y una o dos opciones extra. Se guardan en este navegador y también se envían al asistente como base de sus ejecuciones. «Restablecer originales» recupera los valores iniciales.",
  "Opens a comparison of the four model levels (Hermes, Dionysus, Zeus, Apollo): what each one is good for, how fast and how deep it is, and which model it will use and what it falls back to. Each card has a button to choose it.": "Abre una comparación de los cuatro niveles (Hermes, Dionysus, Zeus, Apollo): para qué sirve cada uno, lo rápido y profundo que es, qué modelo usará y a cuál recurre si falla. Cada tarjeta tiene un botón para elegirlo.",
  "Green when a key is available (on the server or in this tab), amber when it is missing. Click it to open the settings.": "Verde cuando hay una clave (en el servidor o en esta pestaña), ámbar cuando falta. Púlsalo para abrir los ajustes.",
  "Shows who is signed in. Log out, then type another name in Athena’s window to log in. Each name keeps its own history and default parameters. There is no password.": "Muestra quién ha iniciado sesión. Cierra sesión y escribe otro nombre en la ventana de Athena para entrar. Cada nombre tiene su propio historial y parámetros por defecto. No hay contraseña.",
  "Language (English US or UK, Greek, Spanish, German, Italian), colour theme (Light, Dark, Spin), your Anthropic, OpenAI and Gemini API keys, and the model each god uses (Auto by default). The keys stay in this browser tab and are only sent to your own server.": "Idioma (inglés de EE. UU. o del Reino Unido, griego, español, alemán, italiano), tema de color (Claro, Oscuro, Spin), tus claves API de Anthropic, OpenAI y Gemini y el modelo de cada dios (Automático por defecto). Las claves se quedan en esta pestaña y solo se envían a tu servidor.",
  "Attach": "Adjuntar",
  "Adds a parameter .txt file to your message. Dragging a file onto the chat works too.": "Añade un archivo de parámetros .txt a tu mensaje. También puedes arrastrarlo al chat.",
  "Model picker": "Selector de modelo",
  "Fast and Deep": "Fast y Deep",
  "Token counter": "Contador de tokens",
  "Tokens used in the current chat. Each answer also shows its own input and output tokens. Runs started from Run setup use none.": "Tokens usados en el chat actual. Cada respuesta muestra también sus tokens de entrada y salida. Las ejecuciones lanzadas desde Configurar ejecución no usan ninguno.",
  "Sends the message. Enter does the same.": "Envía el mensaje. Enter hace lo mismo.",
  "Run cards": "Tarjetas de ejecución",
  "Every run shows its steps and then the full viewer: a dial with the +x and +z axes, the order before and after (for example AFM→FM), and a plot of m1, m2 and the Néel vector. Click the plot to move the playhead, drag to zoom, double-click to reset, and press Play to animate.": "Cada ejecución muestra sus pasos y luego el visor completo: un dial con los ejes +x y +z, el orden antes y después (por ejemplo AFM→FM) y una gráfica de m1, m2 y el vector de Néel. Pulsa la gráfica para mover el cabezal, arrastra para ampliar, doble clic para restablecer y Reproducir para animar.",
  "Folded cards": "Tarjetas plegadas",
  "Older run cards fold to one line (order, switches, settle time and the parameters you changed) when a new one appears. Click the line or the arrow to open it again; the star marks a run.": "Las tarjetas antiguas se pliegan en una línea (orden, inversiones, tiempo de asentamiento y parámetros cambiados) cuando aparece una nueva. Pulsa la línea o la flecha para abrirla de nuevo; la estrella marca una ejecución.",
  "3D sphere": "Esfera 3D",
  "Figure and Report": "Figura e informe",
  "Next steps and Run button": "Siguientes pasos y botón de ejecución",
  "Export": "Exportar",
  "The owl in the bottom right corner explains how to use the app. She only answers questions about SpinMate itself; for simulations, ask in the chat.": "El búho de la esquina inferior derecha explica cómo usar la aplicación. Solo responde preguntas sobre SpinMate; para simulaciones, pregunta en el chat.",
  "Start a run yourself, without the assistant (no tokens). The result appears in the chat.": "Lanza una ejecución tú mismo, sin el asistente (sin tokens). El resultado aparece en el chat.",
