  "Method, results table, parameters, figures and the parameter files of the runs. It appears in the chat, where you can read it, print it to PDF or download it.": "Método, tabla de resultados, parámetros, figuras y los archivos de parámetros de las ejecuciones. Aparece en el chat, donde puedes leerlo, imprimirlo en PDF o descargarlo.",
