  "Find a skill": "Encuentra una habilidad",
  "Hi, what shall we simulate?": "Hola, ¿qué simulamos?",
  "Hi {name}, what shall we simulate?": "Hola, {name}, ¿qué simulamos?",
  "Describe the conditions in words or attach a parameter file. The agent checks them with the solver's own parser, runs the two-sublattice macrospin model, and explains the result from the real dynamics.": "Describe las condiciones con palabras o adjunta un archivo de parámetros. El agente las comprueba con el propio analizador del solver, ejecuta el modelo macrospin de dos subredes y explica el resultado a partir de la dinámica real.",
  "Parameters": "Parámetros",
  "Start antiferromagnetic with a positive exchange A0 = 0.248e-12, no current, 2 ns. Does it end ferromagnetic?": "Empieza antiferromagnético con un intercambio positivo A0 = 0.248e-12, sin corriente, 2 ns. ¿Acaba ferromagnético?",
  "Start antiferromagnetic with the negative default exchange, no current, 2 ns. Does it stay antiferromagnetic?": "Empieza antiferromagnético con el intercambio negativo por defecto, sin corriente, 2 ns. ¿Sigue antiferromagnético?",
  "Start with nearly parallel sublattices (m1 = 0.25,0,0.968 and m2 = 0.35,0,0.937) and a negative exchange A0 = -0.248e-12, no current, 2 ns. Does it become antiferromagnetic?": "Empieza con subredes casi paralelas (m1 = 0.25,0,0.968 y m2 = 0.35,0,0.937) y un intercambio negativo A0 = -0.248e-12, sin corriente, 2 ns. ¿Se vuelve antiferromagnético?",
  "Start with nearly parallel sublattices (m1 = 0.25,0,0.968 and m2 = 0.35,0,0.937) and a positive exchange A0 = 0.248e-12, no current, 2 ns. Does it stay ferromagnetic?": "Empieza con subredes casi paralelas (m1 = 0.25,0,0.968 y m2 = 0.35,0,0.937) y un intercambio positivo A0 = 0.248e-12, sin corriente, 2 ns. ¿Sigue ferromagnético?",
  "Heat a FeRh layer through its transition: positive A0 = 0.248e-12, temperature 370 K ± 60 K at 0.25 GHz, 2 ns. When does it go from AFM to FM?": "Calienta una capa de FeRh a través de su transición: A0 positivo = 0.248e-12, temperatura 370 K ± 60 K a 0.25 GHz, 2 ns. ¿Cuándo pasa de AFM a FM?",
  "Explain which parameters I can set and their units.": "Explica qué parámetros puedo fijar y sus unidades.",
