  "No model available. Add an API key in Settings.": "No hay modelo disponible. Añade una clave API en Ajustes.",
  "Uses": "Usa",
  "The browser blocks the microphone on this address; open SpinMate on localhost or https.": "El navegador bloquea el micrófono en esta dirección; abre SpinMate en localhost o https.",
  "No OpenAI key: the browser's dictation is used, always with the system default microphone. Add an OpenAI key to choose one.": "Sin clave de OpenAI: se usa el dictado del navegador, siempre con el micrófono por defecto. Añade una clave de OpenAI para elegir uno.",
  "Voice input needs an OpenAI key (Settings).": "La entrada de voz necesita una clave de OpenAI (Ajustes).",
  "Names appear after you allow the microphone once.": "Los nombres aparecen cuando permites el micrófono una vez.",
  "Speech is transcribed by OpenAI and put in the message box; nothing is sent until you press Enter.": "OpenAI transcribe la voz y la pone en el cuadro de mensaje; no se envía nada hasta que pulses Enter.",
  "Recording: click to stop (Esc cancels)": "Grabando: pulsa para parar (Esc cancela)",
  "Transcribing…": "Transcribiendo…",
  "user guide (PDF)": "guía de usuario (PDF)",
  "and the": "y la",
  "presentation (PDF)": "presentación (PDF)",
  "Welcome back, {name}! I'm Athena, your guide.": "¡Bienvenido de nuevo, {name}! Soy Athena, tu guía.",
  "Welcome to SpinMate! I'm Athena, your guide.": "¡Bienvenido a SpinMate! Soy Athena, tu guía.",
  "I can also show you around the app: where things are and what the buttons do.": "También puedo enseñarte la aplicación: dónde está cada cosa y qué hacen los botones.",
  "Before we begin, what's your name?": "Antes de empezar, ¿cómo te llamas?",
  "No problem, no account needed. Here is your {docs}; you can also ask me for them any time. Ask me anything about using SpinMate, or pick a question:": "Sin problema, no hace falta cuenta. Aquí tienes: {docs}; puedes pedírmelos cuando quieras. Pregúntame lo que quieras sobre SpinMate o elige una pregunta:",
  "That doesn't look like an email address. Try again, or press Skip for now.": "Eso no parece una dirección de email. Inténtalo de nuevo o pulsa Omitir por ahora.",
  "Creating your account…": "Creando tu cuenta…",
  "Your account is ready! I've sent a welcome email to **{email}** with the documents attached. You can also open the {docs} here. Ask me anything, or pick a question:": "¡Tu cuenta está lista! He enviado un email de bienvenida a **{email}** con los documentos adjuntos. También puedes abrir aquí: {docs}. Pregúntame lo que quieras o elige una pregunta:",
  "Your account is ready, but the welcome email could not be sent ({error}). Here is your {docs}. Ask me anything, or pick a question:": "Tu cuenta está lista, pero no se pudo enviar el email de bienvenida ({error}). Aquí tienes: {docs}. Pregúntame lo que quieras o elige una pregunta:",
  "Your account is ready! Here is your {docs}. Ask me anything, or pick a question:": "¡Tu cuenta está lista! Aquí tienes: {docs}. Pregúntame lo que quieras o elige una pregunta:",
  "I couldn't create the account: {error}. Try again, or press Skip for now.": "No pude crear la cuenta: {error}. Inténtalo de nuevo o pulsa Omitir por ahora.",
  "I can only help with using SpinMate: the chat, Fast and Deep modes, run setup, runs and results, settings and the API key. Ask me about any of those.": "Solo puedo ayudar con el uso de SpinMate: el chat, los modos Fast y Deep, la configuración de ejecuciones, las ejecuciones y resultados, los ajustes y la clave API. Pregúntame por cualquiera de ellos.",
  "I couldn't read that. Please type just your first name.": "No pude leerlo. Escribe solo tu nombre.",
  "Nice to meet you, {name}! Want an account? Type your email and I'll send you a welcome email with the SpinMate user guide and the presentation. Your email is used for this welcome email and kept by the SpinMate author, only to contact you about SpinMate; write to spinmate.ai.agent@gmail.com to have it deleted. Or press Skip for now: you get them here either way.": "¡Encantada, {name}! ¿Quieres una cuenta? Escribe tu email y te enviaré un email de bienvenida con la guía de usuario de SpinMate y la presentación. Tu email se usa para este mensaje de bienvenida y lo guarda el autor de SpinMate solo para contactarte sobre SpinMate; escribe a spinmate.ai.agent@gmail.com para que lo borre. O pulsa Omitir por ahora: los recibirás aquí igualmente.",
  "Nice to meet you, {name}! Want an account? Type your email and I'll send you a welcome email with the SpinMate user guide. Your email is used for this welcome email and kept by the SpinMate author, only to contact you about SpinMate; write to spinmate.ai.agent@gmail.com to have it deleted. Or press Skip for now: you get them here either way.": "¡Encantada, {name}! ¿Quieres una cuenta? Escribe tu email y te enviaré un email de bienvenida con la guía de usuario de SpinMate. Tu email se usa para este mensaje de bienvenida y lo guarda el autor de SpinMate solo para contactarte sobre SpinMate; escribe a spinmate.ai.agent@gmail.com para que lo borre. O pulsa Omitir por ahora: la recibirás aquí igualmente.",
  "{#n} tokens": "{n} tokens",
  "{#n} tokens · ≈{cost}": "{n} tokens · ≈{cost}",
  "This chat: {#i} in, {#o} out, about {c} at list prices {rest}": "Este chat: {i} de entrada, {o} de salida, unos {c} a precios de lista {rest}",
  "tokens: {#i} in · {#o} out · {#n} total{rest}": "tokens: {i} entrada · {o} salida · {n} total{rest}",
