  "Select {id}": "Seleccionar {id}",
  "{#a} of {#b}": "{a} de {b}",
  "{#n} models from Anthropic, OpenAI and Gemini": "{n} modelos de Anthropic, OpenAI y Gemini",
  "{#n} runs": "{n} ejecuciones",
