  "{god} → no model available, add an API key": "{god} → no hay modelo, añade una clave API",
  "{god} → auto: the strongest model unless a cheaper one is enough for the request": "{god} → automático: el modelo más potente salvo que baste uno más barato",
  "Auto: picks per request from {#n} models by capability and price": "Automático: elige en cada petición entre {n} modelos según capacidad y precio",
