  "Ask another god": "Einen anderen Gott fragen",
  "The same question goes to another model level; both answers stay side by side. Runs it starts appear in the Runs panel.": "Dieselbe Frage geht an eine andere Modellstufe; beide Antworten stehen nebeneinander. Gestartete Läufe erscheinen im Läufe-Bereich.",
