  "steady rotation starts (auto-oscillation)": "stetige Rotation beginnt (Auto-Oszillation)",
  "something else (write it below)": "etwas anderes (unten eintragen)",
  "Give both ends of the range.": "Geben Sie beide Enden des Bereichs an.",
  "The range should go from the smaller to the larger value.": "Der Bereich sollte vom kleineren zum größeren Wert gehen.",
  "{v} {u} is unusual for {p}: check the unit.": "{v} {u} ist für {p} ungewöhnlich: prüfen Sie die Einheit.",
  "Give the duration in ns.": "Geben Sie die Dauer in ns an.",
  "Runs longer than 50 ns take minutes each.": "Läufe über 50 ns dauern jeweils Minuten.",
  "Use at least 2 steps.": "Verwenden Sie mindestens 2 Schritte.",
  "At most {n} runs per sweep on this server.": "Höchstens {n} Läufe pro Sweep auf diesem Server.",
  "More than {n} runs: you will be asked before they start.": "Mehr als {n} Läufe: Sie werden vor dem Start gefragt.",
  "SOT current": "SOT-Strom",
  "Exchange A0": "Austausch A0",
  "Anisotropy Ku": "Anisotropie Ku",
  "DC field H (along Hex_DC)": "DC-Feld H (entlang Hex_DC)",
