  "Saturation Ms": "Sättigung Ms",
  "Drive frequency Fr": "Anregungsfrequenz Fr",
  "AC field amplitude": "AC-Feldamplitude",
  "Pick a parameter in convenient units, the range and the steps (or what to look for), and the duration. It writes a clear request with SI values and warns about unusual numbers.": "Wählen Sie einen Parameter in bequemen Einheiten, den Bereich und die Schritte (oder was gesucht wird) und die Dauer. Es schreibt eine klare Anfrage mit SI-Werten und warnt bei ungewöhnlichen Zahlen.",
  "Click the token counter for the tokens and the cost per day and per provider (Claude, OpenAI, Gemini) of every answer on this server.": "Klicken Sie auf den Token-Zähler für Tokens und Kosten pro Tag und Anbieter (Claude, OpenAI, Gemini) jeder Antwort auf diesem Server.",
  "Under an answer: sends the same question to another model level and shows both answers side by side.": "Unter einer Antwort: schickt dieselbe Frage an eine andere Modellstufe und zeigt beide Antworten nebeneinander.",
  "Usage and cost per provider": "Nutzung und Kosten pro Anbieter",
  "Engine": "Engine",
  "not installed": "nicht installiert",
  "Physics validation": "Physik-Validierung",
  "Physics validation: {#p}/{#n} analytic cases pass · {d}": "Physik-Validierung: {p}/{n} analytische Fälle bestanden · {d}",
  "Physics validation: {#p}/{#n} analytic cases pass": "Physik-Validierung: {p}/{n} analytische Fälle bestanden",
  "Connect to Claude": "Mit Claude verbinden",
  "Use SpinMate from Claude and other agents": "SpinMate aus Claude und anderen Agenten nutzen",
  "Use SpinMate from other agents": "SpinMate aus anderen Agenten nutzen",
  "Any MCP agent": "Jeder MCP-Agent",
  "SpinMate is also an MCP server: Claude Code, Claude Desktop or any MCP agent can run and read simulations with the same tools, runs and queue as this page.": "SpinMate ist auch ein MCP-Server: Claude Code, Claude Desktop oder jeder MCP-Agent kann Simulationen mit denselben Werkzeugen, Läufen und derselben Warteschlange wie diese Seite starten und lesen.",
  "Opening Claude Code in the repository also loads the physics subagent and skill.": "Wenn Sie Claude Code im Repository öffnen, werden auch der Physik-Subagent und der Skill geladen.",
  "Settings > Developer > Edit config (claude_desktop_config.json); change the path to your copy of the repository.": "Einstellungen > Developer > Edit config (claude_desktop_config.json); ändern Sie den Pfad zu Ihrer Kopie des Repositorys.",
  "Streamable HTTP. Large requests return needs_confirmation, so the agent asks you before it runs them.": "Streamable HTTP. Große Anfragen liefern needs_confirmation, daher fragt der Agent Sie, bevor er sie ausführt.",
  "The commands that add SpinMate to Claude Code, Claude Desktop or any MCP agent, with copy buttons.": "Die Befehle, die SpinMate zu Claude Code, Claude Desktop oder jedem MCP-Agenten hinzufügen, mit Kopier-Schaltflächen.",
  "Shows that the solver passes its analytic checks (resonance frequencies, energy, damping, the AFM/FM boundary). Green when all cases pass; click for the full report and the phase diagram.": "Zeigt, dass der Solver seine analytischen Prüfungen besteht (Resonanzfrequenzen, Energie, Dämpfung, die AFM/FM-Grenze). Grün, wenn alle Fälle bestehen; Klick für den vollständigen Bericht und das Phasendiagramm.",
  "Valid. {#n} steps.": "Gültig. {n} Schritte.",
  "Key works": "Schlüssel funktioniert",
  "models": "Modelle",
  "Key not checked": "Schlüssel nicht geprüft",
