  "The keys stay in this browser tab and are sent only to your own server.": "Die Schlüssel bleiben in diesem Tab und gehen nur an Ihren eigenen Server.",
  "Model behind each god": "Modell hinter jedem Gott",
  "Auto scores the god's models from every provider you have a key for (Anthropic, OpenAI, Gemini) by capability and price for each request, and switches to the next one if a call fails. Choose a model to always use it for that god.": "Auto bewertet bei jeder Anfrage die Modelle des Gottes von jedem Anbieter, für den Sie einen Schlüssel haben (Anthropic, OpenAI, Gemini), nach Leistung und Preis und wechselt zum nächsten, wenn ein Aufruf fehlschlägt. Wählen Sie ein Modell, um es für diesen Gott immer zu verwenden.",
