  "you@example.com": "sie@beispiel.de",
  "Skip for now": "Vorerst überspringen",
  "Who are you?": "Wer bist du?",
  "How do I run a simulation?": "Wie starte ich eine Simulation?",
  "What is Fast vs Deep?": "Was ist Fast und was Deep?",
  "Where are my results?": "Wo sind meine Ergebnisse?",
  "How do I change the theme?": "Wie ändere ich das Farbschema?",
  "Four levels, one god each. Pick the level that matches the question: a quick check, an everyday run, or a careful analysis. Larger models usually cost more tokens and take longer to answer.": "Vier Stufen, je ein Gott. Wählen Sie die Stufe, die zur Frage passt: eine schnelle Prüfung, ein alltäglicher Lauf oder eine sorgfältige Analyse. Größere Modelle kosten meist mehr Tokens und antworten langsamer.",
  "Left bar": "Linke Leiste",
  "Under the message box": "Unter dem Nachrichtenfeld",
  "In the chat": "Im Chat",
  "New chat": "Neuer Chat",
  "Starts a fresh conversation. The current one is saved in the history first.": "Startet ein neues Gespräch. Das aktuelle wird vorher im Verlauf gespeichert.",
  "History": "Verlauf",
  "Lists your earlier chats with their runs and graphs. Click one to reopen it, or the cross to delete it. Every user has their own history.": "Listet Ihre früheren Chats mit ihren Läufen und Grafiken. Klicken Sie einen an, um ihn erneut zu öffnen, oder das Kreuz, um ihn zu löschen. Jeder Nutzer hat seinen eigenen Verlauf.",
  "Runs": "Läufe",
  "Edit the values Fast mode starts from: duration, Ms, exchange A0, anisotropy Ku, damping, temperature, SOT current, the initial state and one or two extra flags. They are saved in this browser and also sent to the assistant as the base of its runs. “Reset to built-in” brings back the originals.": "Bearbeiten Sie die Startwerte des Fast-Modus: Dauer, Ms, Austausch A0, Anisotropie Ku, Dämpfung, Temperatur, SOT-Strom, Anfangszustand und ein oder zwei zusätzliche Flags. Sie werden in diesem Browser gespeichert und dem Assistenten als Grundlage seiner Läufe geschickt. „Auf Werkseinstellung“ stellt die Originale wieder her.",
  "Opens a comparison of the four model levels (Hermes, Dionysus, Zeus, Apollo): what each one is good for, how fast and how deep it is, and which model it will use and what it falls back to. Each card has a button to choose it.": "Öffnet einen Vergleich der vier Stufen (Hermes, Dionysus, Zeus, Apollo): wofür jede gut ist, wie schnell und gründlich sie ist, welches Modell sie nutzt und worauf sie ausweicht. Jede Karte hat einen Button zur Auswahl.",
  "Green when a key is available (on the server or in this tab), amber when it is missing. Click it to open the settings.": "Grün, wenn ein Schlüssel vorhanden ist (auf dem Server oder in diesem Tab), gelb, wenn er fehlt. Klicken öffnet die Einstellungen.",
  "Shows who is signed in. Log out, then type another name in Athena’s window to log in. Each name keeps its own history and default parameters. There is no password.": "Zeigt, wer angemeldet ist. Melden Sie sich ab und geben Sie in Athenas Fenster einen anderen Namen ein, um sich anzumelden. Jeder Name hat eigenen Verlauf und eigene Standardparameter. Es gibt kein Passwort.",
  "Language (English US or UK, Greek, Spanish, German, Italian), colour theme (Light, Dark, Spin), your Anthropic, OpenAI and Gemini API keys, and the model each god uses (Auto by default). The keys stay in this browser tab and are only sent to your own server.": "Sprache (Englisch US oder UK, Griechisch, Spanisch, Deutsch, Italienisch), Farbschema (Hell, Dunkel, Spin), Ihre API-Schlüssel für Anthropic, OpenAI und Gemini und das Modell jedes Gottes (standardmäßig Automatisch). Die Schlüssel bleiben in diesem Tab und gehen nur an Ihren Server.",
  "Attach": "Anhängen",
  "Adds a parameter .txt file to your message. Dragging a file onto the chat works too.": "Hängt eine Parameterdatei (.txt) an Ihre Nachricht. Sie können sie auch in den Chat ziehen.",
  "Model picker": "Modellauswahl",
  "Fast and Deep": "Fast und Deep",
  "Token counter": "Token-Zähler",
  "Tokens used in the current chat. Each answer also shows its own input and output tokens. Runs started from Run setup use none.": "Im aktuellen Chat verbrauchte Tokens. Jede Antwort zeigt auch ihre eigenen Ein- und Ausgabe-Tokens. Läufe aus „Lauf einrichten“ verbrauchen keine.",
  "Sends the message. Enter does the same.": "Sendet die Nachricht. Enter macht dasselbe.",
  "Run cards": "Laufkarten",
  "Every run shows its steps and then the full viewer: a dial with the +x and +z axes, the order before and after (for example AFM→FM), and a plot of m1, m2 and the Néel vector. Click the plot to move the playhead, drag to zoom, double-click to reset, and press Play to animate.": "Jeder Lauf zeigt seine Schritte und dann die volle Ansicht: eine Skala mit den Achsen +x und +z, die Ordnung vorher und nachher (zum Beispiel AFM→FM) und ein Diagramm von m1, m2 und dem Néel-Vektor. Klicken Sie ins Diagramm, um die Abspielmarke zu setzen, ziehen zum Zoomen, Doppelklick zum Zurücksetzen und Abspielen für die Animation.",
  "Folded cards": "Eingeklappte Karten",
  "Older run cards fold to one line (order, switches, settle time and the parameters you changed) when a new one appears. Click the line or the arrow to open it again; the star marks a run.": "Ältere Laufkarten klappen auf eine Zeile zusammen (Ordnung, Umschaltungen, Einschwingzeit und geänderte Parameter), sobald eine neue erscheint. Klicken Sie auf die Zeile oder den Pfeil, um sie wieder zu öffnen; der Stern markiert einen Lauf.",
  "3D sphere": "3D-Kugel",
  "Figure and Report": "Abbildung und Bericht",
  "Next steps and Run button": "Nächste Schritte und Start-Button",
  "Export": "Export",
  "The owl in the bottom right corner explains how to use the app. She only answers questions about SpinMate itself; for simulations, ask in the chat.": "Die Eule unten rechts erklärt die Bedienung der App. Sie beantwortet nur Fragen zu SpinMate selbst; für Simulationen fragen Sie im Chat.",
  "Start a run yourself, without the assistant (no tokens). The result appears in the chat.": "Starten Sie selbst einen Lauf, ohne Assistent (keine Tokens). Das Ergebnis erscheint im Chat.",
  "Setup mode": "Einrichtungsmodus",
  "Fast": "Fast",
  "Deep": "Deep",
  "Deep (txt)": "Deep (txt)",
  "Presets": "Vorlagen",
  "FeRh heating": "FeRh-Erwärmung",
  "Initial state": "Anfangszustand",
  "AFM, Néel −z (default)": "AFM, Néel −z (Standard)",
  "Quick extra txt": "Schnelles Zusatz-txt",
