  "Hi, what shall we simulate?": "Hallo, was simulieren wir?",
  "Hi {name}, what shall we simulate?": "Hallo {name}, was simulieren wir?",
  "Describe the conditions in words or attach a parameter file. The agent checks them with the solver's own parser, runs the two-sublattice macrospin model, and explains the result from the real dynamics.": "Beschreiben Sie die Bedingungen in Worten oder hängen Sie eine Parameterdatei an. Der Agent prüft sie mit dem Parser des Solvers, rechnet das Macrospin-Modell mit zwei Untergittern und erklärt das Ergebnis aus der echten Dynamik.",
  "Parameters": "Parameter",
  "Start antiferromagnetic with a positive exchange A0 = 0.248e-12, no current, 2 ns. Does it end ferromagnetic?": "Starte antiferromagnetisch mit positivem Austausch A0 = 0.248e-12, ohne Strom, 2 ns. Endet es ferromagnetisch?",
  "Start antiferromagnetic with the negative default exchange, no current, 2 ns. Does it stay antiferromagnetic?": "Starte antiferromagnetisch mit dem negativen Standardaustausch, ohne Strom, 2 ns. Bleibt es antiferromagnetisch?",
  "Start with nearly parallel sublattices (m1 = 0.25,0,0.968 and m2 = 0.35,0,0.937) and a negative exchange A0 = -0.248e-12, no current, 2 ns. Does it become antiferromagnetic?": "Starte mit fast parallelen Untergittern (m1 = 0.25,0,0.968 und m2 = 0.35,0,0.937) und negativem Austausch A0 = -0.248e-12, ohne Strom, 2 ns. Wird es antiferromagnetisch?",
  "Start with nearly parallel sublattices (m1 = 0.25,0,0.968 and m2 = 0.35,0,0.937) and a positive exchange A0 = 0.248e-12, no current, 2 ns. Does it stay ferromagnetic?": "Starte mit fast parallelen Untergittern (m1 = 0.25,0,0.968 und m2 = 0.35,0,0.937) und positivem Austausch A0 = 0.248e-12, ohne Strom, 2 ns. Bleibt es ferromagnetisch?",
  "Heat a FeRh layer through its transition: positive A0 = 0.248e-12, temperature 370 K ± 60 K at 0.25 GHz, 2 ns. When does it go from AFM to FM?": "Erwärme eine FeRh-Schicht durch ihren Übergang: positives A0 = 0.248e-12, Temperatur 370 K ± 60 K bei 0.25 GHz, 2 ns. Wann geht sie von AFM zu FM über?",
