  "No model available. Add an API key in Settings.": "Kein Modell verfügbar. Fügen Sie in den Einstellungen einen API-Schlüssel hinzu.",
  "Uses": "Nutzt",
  "The browser blocks the microphone on this address; open SpinMate on localhost or https.": "Der Browser sperrt das Mikrofon auf dieser Adresse; öffnen Sie SpinMate über localhost oder https.",
  "No OpenAI key: the browser's dictation is used, always with the system default microphone. Add an OpenAI key to choose one.": "Kein OpenAI-Schlüssel: Es wird das Diktat des Browsers verwendet, immer mit dem Standardmikrofon. Fügen Sie einen OpenAI-Schlüssel hinzu, um eines zu wählen.",
  "Voice input needs an OpenAI key (Settings).": "Die Spracheingabe braucht einen OpenAI-Schlüssel (Einstellungen).",
  "Names appear after you allow the microphone once.": "Die Namen erscheinen, nachdem Sie das Mikrofon einmal erlaubt haben.",
  "Speech is transcribed by OpenAI and put in the message box; nothing is sent until you press Enter.": "Die Sprache wird von OpenAI transkribiert und ins Nachrichtenfeld gesetzt; gesendet wird erst mit Enter.",
  "Recording: click to stop (Esc cancels)": "Aufnahme: klicken zum Beenden (Esc bricht ab)",
  "Transcribing…": "Transkribiere…",
  "user guide (PDF)": "Benutzerhandbuch (PDF)",
  "and the": "und die",
  "presentation (PDF)": "Präsentation (PDF)",
  "Welcome back, {name}! I'm Athena, your guide.": "Willkommen zurück, {name}! Ich bin Athena, Ihre Begleiterin.",
  "Welcome to SpinMate! I'm Athena, your guide.": "Willkommen bei SpinMate! Ich bin Athena, Ihre Begleiterin.",
  "I can also show you around the app: where things are and what the buttons do.": "Ich kann Ihnen auch die App zeigen: wo was ist und was die Buttons tun.",
  "Before we begin, what's your name?": "Bevor wir anfangen: Wie heißen Sie?",
  "No problem, no account needed. Here is your {docs}; you can also ask me for them any time. Ask me anything about using SpinMate, or pick a question:": "Kein Problem, ein Konto ist nicht nötig. Hier bitte: {docs}; Sie können mich jederzeit danach fragen. Fragen Sie mich alles zur Bedienung von SpinMate oder wählen Sie eine Frage:",
  "That doesn't look like an email address. Try again, or press Skip for now.": "Das sieht nicht nach einer E-Mail-Adresse aus. Versuchen Sie es erneut oder drücken Sie Vorerst überspringen.",
  "Creating your account…": "Ihr Konto wird erstellt…",
  "Your account is ready! I've sent a welcome email to **{email}** with the documents attached. You can also open the {docs} here. Ask me anything, or pick a question:": "Ihr Konto ist bereit! Ich habe eine Willkommens-E-Mail mit den Dokumenten an **{email}** geschickt. Hier können Sie sie auch öffnen: {docs}. Fragen Sie mich alles oder wählen Sie eine Frage:",
  "Your account is ready, but the welcome email could not be sent ({error}). Here is your {docs}. Ask me anything, or pick a question:": "Ihr Konto ist bereit, aber die Willkommens-E-Mail konnte nicht gesendet werden ({error}). Hier bitte: {docs}. Fragen Sie mich alles oder wählen Sie eine Frage:",
  "Your account is ready! Here is your {docs}. Ask me anything, or pick a question:": "Ihr Konto ist bereit! Hier bitte: {docs}. Fragen Sie mich alles oder wählen Sie eine Frage:",
  "I couldn't create the account: {error}. Try again, or press Skip for now.": "Ich konnte das Konto nicht anlegen: {error}. Versuchen Sie es erneut oder drücken Sie Vorerst überspringen.",
  "I can only help with using SpinMate: the chat, Fast and Deep modes, run setup, runs and results, settings and the API key. Ask me about any of those.": "Ich helfe nur bei der Bedienung von SpinMate: Chat, Fast- und Deep-Modus, Lauf einrichten, Läufe und Ergebnisse, Einstellungen und API-Schlüssel. Fragen Sie mich dazu.",
  "I couldn't read that. Please type just your first name.": "Das konnte ich nicht lesen. Bitte geben Sie nur Ihren Vornamen ein.",
  "Nice to meet you, {name}! Want an account? Type your email and I'll send you a welcome email with the SpinMate user guide and the presentation. Your email is used for this welcome email and kept by the SpinMate author, only to contact you about SpinMate; write to spinmate.ai.agent@gmail.com to have it deleted. Or press Skip for now: you get them here either way.": "Freut mich, {name}! Möchten Sie ein Konto? Geben Sie Ihre E-Mail ein und ich schicke Ihnen eine Willkommens-E-Mail mit dem SpinMate-Benutzerhandbuch und der Präsentation. Ihre E-Mail wird für diese Willkommens-E-Mail verwendet und vom Autor von SpinMate nur aufbewahrt, um Sie zu SpinMate zu kontaktieren; schreiben Sie an spinmate.ai.agent@gmail.com, um sie löschen zu lassen. Oder drücken Sie Vorerst überspringen: Sie bekommen beides auch hier.",
  "Nice to meet you, {name}! Want an account? Type your email and I'll send you a welcome email with the SpinMate user guide. Your email is used for this welcome email and kept by the SpinMate author, only to contact you about SpinMate; write to spinmate.ai.agent@gmail.com to have it deleted. Or press Skip for now: you get them here either way.": "Freut mich, {name}! Möchten Sie ein Konto? Geben Sie Ihre E-Mail ein und ich schicke Ihnen eine Willkommens-E-Mail mit dem SpinMate-Benutzerhandbuch. Ihre E-Mail wird für diese Willkommens-E-Mail verwendet und vom Autor von SpinMate nur aufbewahrt, um Sie zu SpinMate zu kontaktieren; schreiben Sie an spinmate.ai.agent@gmail.com, um sie löschen zu lassen. Oder drücken Sie Vorerst überspringen: Sie bekommen es auch hier.",
