  "Ask another god": "Chiedi a un altro dio",
  "The same question goes to another model level; both answers stay side by side. Runs it starts appear in the Runs panel.": "La stessa domanda va a un altro livello di modello; le due risposte restano affiancate. I run avviati compaiono nel pannello dei run.",
