  "e.g. A0 = 0.248e-12, field 0.1 T along z, T = 0": "es. A0 = 0.248e-12, campo 0.1 T lungo z, T = 0",
  "Put in the message box": "Metti nella casella del messaggio",
  "the Néel vector switches": "il vettore di Néel si inverte",
  "the order changes from AFM to FM": "l'ordine passa da AFM a FM",
  "steady rotation starts (auto-oscillation)": "inizia la rotazione stabile (auto-oscillazione)",
  "something else (write it below)": "altro (scrivilo sotto)",
  "Give both ends of the range.": "Indica entrambi gli estremi dell'intervallo.",
  "The range should go from the smaller to the larger value.": "L'intervallo deve andare dal valore minore al maggiore.",
  "{v} {u} is unusual for {p}: check the unit.": "{v} {u} è insolito per {p}: controlla l'unità.",
  "Give the duration in ns.": "Indica la durata in ns.",
  "Runs longer than 50 ns take minutes each.": "I run oltre 50 ns richiedono minuti ciascuno.",
  "Use at least 2 steps.": "Usa almeno 2 passi.",
