  "AC field amplitude": "Ampiezza del campo AC",
  "Pick a parameter in convenient units, the range and the steps (or what to look for), and the duration. It writes a clear request with SI values and warns about unusual numbers.": "Scegli un parametro in unità comode, l'intervallo e i passi (o cosa cercare) e la durata. Scrive una richiesta chiara con valori SI e avvisa dei numeri insoliti.",
  "Click the token counter for the tokens and the cost per day and per provider (Claude, OpenAI, Gemini) of every answer on this server.": "Clicca sul contatore dei token per vedere token e costi per giorno e per fornitore (Claude, OpenAI, Gemini) di ogni risposta su questo server.",
  "Under an answer: sends the same question to another model level and shows both answers side by side.": "Sotto una risposta: invia la stessa domanda a un altro livello di modello e mostra le due risposte affiancate.",
  "Usage and cost per provider": "Uso e costi per fornitore",
  "Engine": "Motore",
  "not installed": "non installato",
  "Physics validation": "Validazione fisica",
  "Physics validation: {#p}/{#n} analytic cases pass · {d}": "Validazione fisica: {p}/{n} casi analitici superati · {d}",
  "Physics validation: {#p}/{#n} analytic cases pass": "Validazione fisica: {p}/{n} casi analitici superati",
  "Connect to Claude": "Collega a Claude",
  "Use SpinMate from Claude and other agents": "Usa SpinMate da Claude e altri agenti",
  "Use SpinMate from other agents": "Usa SpinMate da altri agenti",
  "Any MCP agent": "Qualsiasi agente MCP",
  "SpinMate is also an MCP server: Claude Code, Claude Desktop or any MCP agent can run and read simulations with the same tools, runs and queue as this page.": "SpinMate è anche un server MCP: Claude Code, Claude Desktop o qualsiasi agente MCP può eseguire e leggere simulazioni con gli stessi strumenti, run e coda di questa pagina.",
  "Opening Claude Code in the repository also loads the physics subagent and skill.": "Aprendo Claude Code nel repository si caricano anche il subagente e la skill di fisica.",
  "Settings > Developer > Edit config (claude_desktop_config.json); change the path to your copy of the repository.": "Impostazioni > Developer > Edit config (claude_desktop_config.json); cambia il percorso con la tua copia del repository.",
  "Streamable HTTP. Large requests return needs_confirmation, so the agent asks you before it runs them.": "Streamable HTTP. Le richieste grandi restituiscono needs_confirmation, quindi l'agente ti chiede prima di eseguirle.",
  "The commands that add SpinMate to Claude Code, Claude Desktop or any MCP agent, with copy buttons.": "I comandi che aggiungono SpinMate a Claude Code, Claude Desktop o qualsiasi agente MCP, con pulsanti per copiare.",
  "Shows that the solver passes its analytic checks (resonance frequencies, energy, damping, the AFM/FM boundary). Green when all cases pass; click for the full report and the phase diagram.": "Mostra che il solver supera i suoi controlli analitici (frequenze di risonanza, energia, smorzamento, il confine AFM/FM). Verde quando tutti i casi passano; clicca per il report completo e il diagramma di fase.",
  "Valid. {#n} steps.": "Valido. {n} passi.",
