  "Auto scores the god's models from every provider you have a key for (Anthropic, OpenAI, Gemini) by capability and price for each request, and switches to the next one if a call fails. Choose a model to always use it for that god.": "Auto valuta a ogni richiesta i modelli del dio di ogni fornitore per cui hai una chiave (Anthropic, OpenAI, Gemini) in base a capacità e prezzo, e passa al successivo se una chiamata fallisce. Scegli un modello per usarlo sempre con quel dio.",
