  "Skip for now": "Salta per ora",
  "Who are you?": "Chi sei?",
  "How do I run a simulation?": "Come avvio una simulazione?",
  "What is Fast vs Deep?": "Cosa sono Fast e Deep?",
  "Where are my results?": "Dove sono i miei risultati?",
  "How do I change the theme?": "Come cambio il tema?",
  "Four levels, one god each. Pick the level that matches the question: a quick check, an everyday run, or a careful analysis. Larger models usually cost more tokens and take longer to answer.": "Quattro livelli, un dio ciascuno. Scegli il livello adatto alla domanda: un controllo rapido, un'esecuzione quotidiana o un'analisi accurata. I modelli più grandi di solito costano più token e rispondono più lentamente.",
  "Left bar": "Barra sinistra",
  "Under the message box": "Sotto la casella del messaggio",
  "In the chat": "Nella chat",
  "New chat": "Nuova chat",
  "Starts a fresh conversation. The current one is saved in the history first.": "Avvia una nuova conversazione. Quella attuale viene prima salvata nella cronologia.",
  "History": "Cronologia",
  "Lists your earlier chats with their runs and graphs. Click one to reopen it, or the cross to delete it. Every user has their own history.": "Elenca le chat precedenti con le loro esecuzioni e i grafici. Clicca su una per riaprirla o sulla croce per eliminarla. Ogni utente ha la propria cronologia.",
  "Runs": "Esecuzioni",
  "Edit the values Fast mode starts from: duration, Ms, exchange A0, anisotropy Ku, damping, temperature, SOT current, the initial state and one or two extra flags. They are saved in this browser and also sent to the assistant as the base of its runs. “Reset to built-in” brings back the originals.": "Modifica i valori di partenza della modalità Fast: durata, Ms, scambio A0, anisotropia Ku, smorzamento, temperatura, corrente SOT, lo stato iniziale e uno o due flag extra. Sono salvati in questo browser e inviati anche all'assistente come base delle sue esecuzioni. «Ripristina originali» riporta i valori iniziali.",
  "Opens a comparison of the four model levels (Hermes, Dionysus, Zeus, Apollo): what each one is good for, how fast and how deep it is, and which model it will use and what it falls back to. Each card has a button to choose it.": "Apre un confronto dei quattro livelli (Hermes, Dionysus, Zeus, Apollo): a cosa serve ciascuno, quanto è veloce e approfondito, quale modello userà e su quale ripiega. Ogni scheda ha un pulsante per sceglierlo.",
  "Green when a key is available (on the server or in this tab), amber when it is missing. Click it to open the settings.": "Verde quando c'è una chiave (sul server o in questa scheda), ambra quando manca. Cliccalo per aprire le impostazioni.",
  "Shows who is signed in. Log out, then type another name in Athena’s window to log in. Each name keeps its own history and default parameters. There is no password.": "Mostra chi ha effettuato l'accesso. Esci e scrivi un altro nome nella finestra di Athena per accedere. Ogni nome ha la propria cronologia e i propri parametri predefiniti. Non c'è password.",
  "Language (English US or UK, Greek, Spanish, German, Italian), colour theme (Light, Dark, Spin), your Anthropic, OpenAI and Gemini API keys, and the model each god uses (Auto by default). The keys stay in this browser tab and are only sent to your own server.": "Lingua (inglese US o UK, greco, spagnolo, tedesco, italiano), tema colori (Chiaro, Scuro, Spin), le chiavi API di Anthropic, OpenAI e Gemini e il modello di ogni dio (Automatico di default). Le chiavi restano in questa scheda e vanno solo al tuo server.",
  "Attach": "Allega",
  "Adds a parameter .txt file to your message. Dragging a file onto the chat works too.": "Aggiunge un file di parametri .txt al messaggio. Puoi anche trascinarlo nella chat.",
  "Model picker": "Selettore del modello",
  "Fast and Deep": "Fast e Deep",
  "Token counter": "Contatore token",
  "Tokens used in the current chat. Each answer also shows its own input and output tokens. Runs started from Run setup use none.": "Token usati nella chat attuale. Ogni risposta mostra anche i propri token di input e output. Le esecuzioni avviate da Imposta esecuzione non ne usano.",
  "Sends the message. Enter does the same.": "Invia il messaggio. Anche Invio fa lo stesso.",
  "Run cards": "Schede delle esecuzioni",
  "Every run shows its steps and then the full viewer: a dial with the +x and +z axes, the order before and after (for example AFM→FM), and a plot of m1, m2 and the Néel vector. Click the plot to move the playhead, drag to zoom, double-click to reset, and press Play to animate.": "Ogni esecuzione mostra i suoi passi e poi il visualizzatore completo: un quadrante con gli assi +x e +z, l'ordine prima e dopo (per esempio AFM→FM) e un grafico di m1, m2 e del vettore di Néel. Clicca sul grafico per spostare l'indicatore, trascina per ingrandire, doppio clic per ripristinare e Riproduci per animare.",
  "Folded cards": "Schede compresse",
  "Older run cards fold to one line (order, switches, settle time and the parameters you changed) when a new one appears. Click the line or the arrow to open it again; the star marks a run.": "Le schede più vecchie si compattano in una riga (ordine, inversioni, tempo di assestamento e parametri modificati) quando ne compare una nuova. Clicca la riga o la freccia per riaprirla; la stella contrassegna un'esecuzione.",
  "3D sphere": "Sfera 3D",
  "Figure and Report": "Figura e report",
  "Next steps and Run button": "Passi successivi e pulsante di avvio",
  "Export": "Esporta",
  "The owl in the bottom right corner explains how to use the app. She only answers questions about SpinMate itself; for simulations, ask in the chat.": "Il gufo in basso a destra spiega come usare l'app. Risponde solo a domande su SpinMate; per le simulazioni chiedi nella chat.",
  "Start a run yourself, without the assistant (no tokens). The result appears in the chat.": "Avvia tu un'esecuzione, senza l'assistente (nessun token). Il risultato compare nella chat.",
