  "Method, results table, parameters, figures and the parameter files of the runs. It appears in the chat, where you can read it, print it to PDF or download it.": "Metodo, tabella dei risultati, parametri, figure e i file di parametri delle esecuzioni. Compare nella chat, dove puoi leggerlo, stamparlo in PDF o scaricarlo.",
