  "Hi, what shall we simulate?": "Ciao, cosa simuliamo?",
  "Hi {name}, what shall we simulate?": "Ciao {name}, cosa simuliamo?",
  "Describe the conditions in words or attach a parameter file. The agent checks them with the solver's own parser, runs the two-sublattice macrospin model, and explains the result from the real dynamics.": "Descrivi le condizioni a parole o allega un file di parametri. L'agente le verifica con il parser del solver, esegue il modello macrospin a due sottoreticoli e spiega il risultato dalla dinamica reale.",
  "Parameters": "Parametri",
  "Start antiferromagnetic with a positive exchange A0 = 0.248e-12, no current, 2 ns. Does it end ferromagnetic?": "Parti antiferromagnetico con uno scambio positivo A0 = 0.248e-12, senza corrente, 2 ns. Finisce ferromagnetico?",
  "Start antiferromagnetic with the negative default exchange, no current, 2 ns. Does it stay antiferromagnetic?": "Parti antiferromagnetico con lo scambio negativo predefinito, senza corrente, 2 ns. Resta antiferromagnetico?",
  "Start with nearly parallel sublattices (m1 = 0.25,0,0.968 and m2 = 0.35,0,0.937) and a negative exchange A0 = -0.248e-12, no current, 2 ns. Does it become antiferromagnetic?": "Parti con sottoreticoli quasi paralleli (m1 = 0.25,0,0.968 e m2 = 0.35,0,0.937) e uno scambio negativo A0 = -0.248e-12, senza corrente, 2 ns. Diventa antiferromagnetico?",
  "Start with nearly parallel sublattices (m1 = 0.25,0,0.968 and m2 = 0.35,0,0.937) and a positive exchange A0 = 0.248e-12, no current, 2 ns. Does it stay ferromagnetic?": "Parti con sottoreticoli quasi paralleli (m1 = 0.25,0,0.968 e m2 = 0.35,0,0.937) e uno scambio positivo A0 = 0.248e-12, senza corrente, 2 ns. Resta ferromagnetico?",
  "Heat a FeRh layer through its transition: positive A0 = 0.248e-12, temperature 370 K ± 60 K at 0.25 GHz, 2 ns. When does it go from AFM to FM?": "Riscalda uno strato di FeRh attraverso la sua transizione: A0 positivo = 0.248e-12, temperatura 370 K ± 60 K a 0.25 GHz, 2 ns. Quando passa da AFM a FM?",
  "Explain which parameters I can set and their units.": "Spiega quali parametri posso impostare e le loro unità.",
