  "varies": "varia",
  "No model available. Add an API key in Settings.": "Nessun modello disponibile. Aggiungi una chiave API nelle Impostazioni.",
  "Uses": "Usa",
  "The browser blocks the microphone on this address; open SpinMate on localhost or https.": "Il browser blocca il microfono a questo indirizzo; apri SpinMate su localhost o https.",
  "No OpenAI key: the browser's dictation is used, always with the system default microphone. Add an OpenAI key to choose one.": "Nessuna chiave OpenAI: si usa la dettatura del browser, sempre con il microfono predefinito. Aggiungi una chiave OpenAI per sceglierne uno.",
  "Voice input needs an OpenAI key (Settings).": "L'input vocale richiede una chiave OpenAI (Impostazioni).",
  "Names appear after you allow the microphone once.": "I nomi compaiono dopo aver consentito il microfono una volta.",
  "Speech is transcribed by OpenAI and put in the message box; nothing is sent until you press Enter.": "Il parlato viene trascritto da OpenAI e messo nella casella; non viene inviato nulla finché non premi Invio.",
  "Recording: click to stop (Esc cancels)": "Registrazione: clicca per fermare (Esc annulla)",
  "Transcribing…": "Trascrizione…",
  "user guide (PDF)": "guida utente (PDF)",
  "and the": "e la",
  "presentation (PDF)": "presentazione (PDF)",
  "Welcome back, {name}! I'm Athena, your guide.": "Bentornato, {name}! Sono Athena, la tua guida.",
  "Welcome to SpinMate! I'm Athena, your guide.": "Benvenuto in SpinMate! Sono Athena, la tua guida.",
  "I can also show you around the app: where things are and what the buttons do.": "Posso anche mostrarti l'app: dove si trovano le cose e cosa fanno i pulsanti.",
  "Before we begin, what's your name?": "Prima di iniziare, come ti chiami?",
  "No problem, no account needed. Here is your {docs}; you can also ask me for them any time. Ask me anything about using SpinMate, or pick a question:": "Nessun problema, l'account non serve. Ecco: {docs}; puoi chiedermeli quando vuoi. Chiedimi qualsiasi cosa sull'uso di SpinMate o scegli una domanda:",
  "That doesn't look like an email address. Try again, or press Skip for now.": "Non sembra un indirizzo email. Riprova o premi Salta per ora.",
  "Creating your account…": "Creazione dell'account…",
  "Your account is ready! I've sent a welcome email to **{email}** with the documents attached. You can also open the {docs} here. Ask me anything, or pick a question:": "Il tuo account è pronto! Ho inviato un'email di benvenuto a **{email}** con i documenti in allegato. Puoi aprirli anche qui: {docs}. Chiedimi qualsiasi cosa o scegli una domanda:",
  "Your account is ready, but the welcome email could not be sent ({error}). Here is your {docs}. Ask me anything, or pick a question:": "Il tuo account è pronto, ma non è stato possibile inviare l'email di benvenuto ({error}). Ecco: {docs}. Chiedimi qualsiasi cosa o scegli una domanda:",
  "Your account is ready! Here is your {docs}. Ask me anything, or pick a question:": "Il tuo account è pronto! Ecco: {docs}. Chiedimi qualsiasi cosa o scegli una domanda:",
  "I couldn't create the account: {error}. Try again, or press Skip for now.": "Non sono riuscita a creare l'account: {error}. Riprova o premi Salta per ora.",
  "I can only help with using SpinMate: the chat, Fast and Deep modes, run setup, runs and results, settings and the API key. Ask me about any of those.": "Posso aiutare solo con l'uso di SpinMate: la chat, le modalità Fast e Deep, l'impostazione delle esecuzioni, esecuzioni e risultati, le impostazioni e la chiave API. Chiedimi pure di questi.",
  "I couldn't read that. Please type just your first name.": "Non sono riuscita a leggerlo. Scrivi solo il tuo nome.",
  "Nice to meet you, {name}! Want an account? Type your email and I'll send you a welcome email with the SpinMate user guide and the presentation. Your email is used for this welcome email and kept by the SpinMate author, only to contact you about SpinMate; write to spinmate.ai.agent@gmail.com to have it deleted. Or press Skip for now: you get them here either way.": "Piacere, {name}! Vuoi un account? Scrivi la tua email e ti invierò un'email di benvenuto con la guida utente di SpinMate e la presentazione. La tua email serve per questo messaggio di benvenuto e viene conservata dall'autore di SpinMate solo per contattarti su SpinMate; scrivi a spinmate.ai.agent@gmail.com per farla cancellare. Oppure premi Salta per ora: li ricevi qui comunque.",
  "Nice to meet you, {name}! Want an account? Type your email and I'll send you a welcome email with the SpinMate user guide. Your email is used for this welcome email and kept by the SpinMate author, only to contact you about SpinMate; write to spinmate.ai.agent@gmail.com to have it deleted. Or press Skip for now: you get them here either way.": "Piacere, {name}! Vuoi un account? Scrivi la tua email e ti invierò un'email di benvenuto con la guida utente di SpinMate. La tua email serve per questo messaggio di benvenuto e viene conservata dall'autore di SpinMate solo per contattarti su SpinMate; scrivi a spinmate.ai.agent@gmail.com per farla cancellare. Oppure premi Salta per ora: la ricevi qui comunque.",
